questions.solution:
class InvalidEmail(Exception):
    pass

def check_email(email):
    if '@' not in email:
        raise InvalidEmail(email)
    return email.lower()

tests.code:
try:
    check_email('ana.mail.com')
except InvalidEmail as e:
    assert str(e) == 'ana.mail.com', 'Use the email as the message.'
else:
    raise AssertionError('An email without @ should raise InvalidEmail.')

