def load_number(text):
    try:
        return float(text)
    except ValueError as err:
        raise ValueError(f"not a number: {text}") from err

tests.code:
try:
    load_number('abc')
except ValueError as e:
    assert str(e) == 'not a number: abc', 'Use the message: not a number: abc'
    assert isinstance(e.__cause__, ValueError), 'Raise it from the original error (raise … from err).'
else:
    raise AssertionError('load_number("abc") should raise ValueError.')

