questions.solution:
def safe_average(values):
    numbers = []
    for v in values:
        try:
            numbers.append(float(v))
        except ValueError:
            continue
    if not numbers:
        raise ValueError("no valid numbers")
    return round(sum(numbers) / len(numbers), 2)

tests.code:
try:
    safe_average(['a', 'b'])
except ValueError as e:
    assert str(e) == 'no valid numbers', 'Use the message: no valid numbers'
else:
    raise AssertionError('No valid numbers should raise ValueError.')
